using LUMAR_ERP_API_V2.DTOs.Employees;
using LUMAR_ERP_API_V2.Repositories;
namespace LUMAR_ERP_API_V2.Services;
public sealed class EmployeeService(IEmployeeRepository repository) : IEmployeeService { public Task<IReadOnlyList<EmployeeListDto>> GetAllAsync(CancellationToken ct) => repository.GetAllAsync(ct); public Task<EmployeeDetailsDto?> GetByIdAsync(int id, CancellationToken ct) => repository.GetByIdAsync(id, ct); public Task<IReadOnlyList<DepartmentDto>> GetDepartmentsAsync(CancellationToken ct) => repository.GetDepartmentsAsync(ct); public Task<IReadOnlyList<EmployeeAttendanceDto>> GetAttendanceAsync(int id, CancellationToken ct) => repository.GetAttendanceAsync(id, ct); public Task<IReadOnlyList<LeaveRequestDto>> GetLeaveRequestsAsync(int id, CancellationToken ct) => repository.GetLeaveRequestsAsync(id, ct); public Task<IReadOnlyList<EmployeeDrawDto>> GetDrawsAsync(string code, CancellationToken ct) => repository.GetDrawsAsync(code, ct); public Task<IReadOnlyList<EmployeeDocumentDto>> GetDocumentsAsync(int id, CancellationToken ct) => repository.GetDocumentsAsync(id, ct); public Task<IReadOnlyList<EmployeeWorkflowDto>> GetWorkflowAsync(string code, CancellationToken ct) => repository.GetWorkflowAsync(code, ct); }